syntax = "proto3";

package kvstore;

service KVStore {
  rpc GetVal(GetValRequest) returns (GetValResponse);
  rpc SetVal(SetValRequest) returns (SetValResponse);
}

message GetValRequest {
  string key = 1;
}

message GetValResponse {
  int32 val = 1;
}

message SetValRequest {
  string key = 1;
  int32 value = 2;
}

message SetValResponse {
  int32 val = 1;
}

import grpc
from concurrent import futures

import kv_store_pb2 as pb
import kv_store_pb2_grpc as pb_grpc

PORT = 5328


class Server(pb_grpc.KVStoreServicer):
    """Implementation of the KVStore service backed by an in-memory dict."""

    def __init__(self):
        self.store = {}

    def GetVal(self, request, context):
        val = self.store.get(request.key, 0)
        return pb.GetValResponse(val=val)

    def SetVal(self, request, context):
        self.store[request.key] = request.value
        return pb.SetValResponse(val=request.value)


def serve():
    server = grpc.server(futures.ThreadPoolExecutor(max_workers=10))
    pb_grpc.add_KVStoreServicer_to_server(Server(), server)
    server.add_insecure_port(f"[::]:{PORT}")
    server.start()
    print(f"KVStore server listening on port {PORT}")
    server.wait_for_termination()


if __name__ == "__main__":
    serve()
